using AcademyDesk.Api.Data;using AcademyDesk.Api.Domain.Entities;using Microsoft.AspNetCore.Mvc;using Microsoft.EntityFrameworkCore;
namespace AcademyDesk.Api.Controllers;
[ApiController][Route("api/academies/{academyId:guid}/batch-promotions")]public sealed class BatchPromotionsController(AcademyDeskDbContext db):ControllerBase{[HttpGet]public async Task<ActionResult> List(Guid academyId,CancellationToken t)=>Ok(await db.BatchPromotions.AsNoTracking().Where(x=>x.AcademyId==academyId).OrderByDescending(x=>x.EffectiveDate).ToListAsync(t));[HttpPost]public async Task<ActionResult> Create(Guid academyId,PromotionRequest r,CancellationToken t){if(r.SourceBatchId==r.TargetBatchId||!await db.Enrollments.AnyAsync(x=>x.AcademyId==academyId&&x.StudentId==r.StudentId&&x.BatchId==r.SourceBatchId&&x.Status=="Active",t)||!await db.Batches.AnyAsync(x=>x.AcademyId==academyId&&x.Id==r.TargetBatchId,t))return BadRequest();db.BatchPromotions.Add(new BatchPromotion{AcademyId=academyId,StudentId=r.StudentId,SourceBatchId=r.SourceBatchId,TargetBatchId=r.TargetBatchId,EffectiveDate=r.EffectiveDate,Notes=r.Notes?.Trim()});await db.SaveChangesAsync(t);return Ok();}[HttpPatch("{id:guid}/decision")]public async Task<ActionResult> Decide(Guid academyId,Guid id,PromotionDecision r,CancellationToken t){var x=await db.BatchPromotions.SingleOrDefaultAsync(x=>x.Id==id&&x.AcademyId==academyId,t);if(x is null)return NotFound();if(r.Status is not("Approved"or"Rejected"))return BadRequest();x.Status=r.Status;x.Notes=r.Notes?.Trim()??x.Notes;await db.SaveChangesAsync(t);return Ok();}}
public sealed record PromotionRequest(Guid StudentId,Guid SourceBatchId,Guid TargetBatchId,DateOnly EffectiveDate,string? Notes);public sealed record PromotionDecision(string Status,string? Notes);
